import base64

ciphertext = """"""

# 1. فك Base64
decoded_morse = base64.b64decode(ciphertext).decode('utf-8')

# 2. تحويل مورس إلى باينري ثم أحرف
raw_bytes = []
for line in decoded_morse.strip().split('\n'):
    binary_str = ""
    for symbol in line.strip().split(' '):
        if symbol == '-----':
            binary_str += '0'
        elif symbol == '.----':
            binary_str += '1'
    if binary_str:
        raw_bytes.append(int(binary_str, 2))

# 3. تعديل الإزاحة العكسية (Shift Decryption)
clear_text = "".join([chr((b - 0x10) if b >= 0x20 else b) for b in raw_bytes[::-1]])

print("\n" + "="*40)
print("الـ FLAG النهائي الصحيح 100% هو:")
print(clear_text)
print("="*40 + "\n")
